-- Purpose: define job_postings; demonstrates keys, constraints and normalized relational ownership.
CREATE TABLE job_postings (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  company_id INT UNSIGNED NOT NULL,
