  location VARCHAR(160) NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_job_postings_companies FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE RESTRICT,
  CONSTRAINT chk_job_postings_title CHECK (CHAR_LENGTH(TRIM(title)) > 0),
  CONSTRAINT chk_job_postings_description CHECK (CHAR_LENGTH(TRIM(description)) > 0),
  CONSTRAINT chk_job_postings_ctc CHECK (ctc_lpa >= 0),
  CONSTRAINT chk_job_postings_active CHECK (is_active IN (0,1)),
  INDEX idx_job_postings_company (company_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Purpose: define placement_drives; demonstrates keys, constraints and normalized relational ownership.
CREATE TABLE placement_drives (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  job_posting_id INT UNSIGNED NOT NULL,
  title VARCHAR(160) NOT NULL,
  description TEXT NULL,
  status ENUM('draft','published','completed','cancelled','archived') NOT NULL DEFAULT 'draft',
  registration_deadline DATETIME NOT NULL,
  drive_date DATETIME NULL,
  min_cgpa DECIMAL(4,2) NULL,
  max_active_backlogs SMALLINT UNSIGNED NULL,
  eligible_graduation_year SMALLINT UNSIGNED NULL,
  created_by INT UNSIGNED NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_placement_drives_postings FOREIGN KEY (job_posting_id) REFERENCES job_postings(id) ON DELETE RESTRICT,
  CONSTRAINT fk_placement_drives_users FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT chk_placement_drives_title CHECK (CHAR_LENGTH(TRIM(title)) > 0),
  CONSTRAINT chk_placement_drives_cgpa CHECK (min_cgpa BETWEEN 0 AND 10),
  CONSTRAINT chk_placement_drives_year CHECK (eligible_graduation_year BETWEEN 2000 AND 2200),
  INDEX idx_drives_status_deadline (status, registration_deadline)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Purpose: define drive_eligible_branches; demonstrates keys, constraints and normalized relational ownership.
CREATE TABLE drive_eligible_branches (
  drive_id INT UNSIGNED NOT NULL,
  branch_id INT UNSIGNED NOT NULL,
  PRIMARY KEY (drive_id, branch_id),
  CONSTRAINT fk_drive_eligible_branches_drives FOREIGN KEY (drive_id) REFERENCES placement_drives(id) ON DELETE CASCADE,
  CONSTRAINT fk_drive_eligible_branches_branches FOREIGN KEY (branch_id) REFERENCES branches(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Purpose: define student_applications; demonstrates keys, constraints and normalized relational ownership.
CREATE TABLE student_applications (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  drive_id INT UNSIGNED NOT NULL,
  student_id INT UNSIGNED NOT NULL,
  status ENUM('applied','shortlisted','selected','rejected','withdrawn') NOT NULL DEFAULT 'applied',
  applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT uq_applications_drive_student UNIQUE (drive_id, student_id),
  CONSTRAINT fk_student_applications_drives FOREIGN KEY (drive_id) REFERENCES placement_drives(id) ON DELETE RESTRICT,
  CONSTRAINT fk_student_applications_students FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE RESTRICT,
  INDEX idx_applications_student_status (student_id, status),
  INDEX idx_applications_drive_status (drive_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Purpose: define application_status_history; demonstrates keys, constraints and normalized relational ownership.
CREATE TABLE application_status_history (
  id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  application_id INT UNSIGNED NOT NULL,
  from_status ENUM('applied','shortlisted','selected','rejected','withdrawn') NULL,
  to_status ENUM('applied','shortlisted','selected','rejected','withdrawn') NOT NULL,
  changed_by INT UNSIGNED NOT NULL,
  remarks VARCHAR(1000) NULL,
  changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_application_history_applications FOREIGN KEY (application_id) REFERENCES student_applications(id) ON DELETE RESTRICT,
  CONSTRAINT fk_application_history_users FOREIGN KEY (changed_by) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT chk_application_history_change CHECK (from_status IS NULL OR from_status <> to_status),
  INDEX idx_history_application_changed (application_id, changed_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Purpose: v_drive_overview; demonstrates joins, subqueries or aggregation without duplicated master data.
CREATE SQL SECURITY INVOKER VIEW v_drive_overview AS
SELECT d.id, d.title, d.status, d.registration_deadline, d.drive_date,
       d.min_cgpa, d.max_active_backlogs, d.eligible_graduation_year,
       j.id AS job_posting_id, j.title AS job_title, j.job_type, j.ctc_lpa,
       c.id AS company_id, c.name AS company_name
FROM placement_drives AS d
JOIN job_postings AS j ON j.id = d.job_posting_id
JOIN companies AS c ON c.id = j.company_id;

-- Purpose: v_student_academic_summary; demonstrates joins, subqueries or aggregation without duplicated master data.
CREATE SQL SECURITY INVOKER VIEW v_student_academic_summary AS
SELECT s.id AS student_id, s.branch_id, s.graduation_year,
       a.semester, a.sgpa, a.cgpa, a.active_backlogs
FROM students AS s
LEFT JOIN academic_records AS a ON a.student_id = s.id
  AND a.semester = (SELECT MAX(latest.semester) FROM academic_records AS latest WHERE latest.student_id = s.id);

-- Purpose: v_application_details; demonstrates joins, subqueries or aggregation without duplicated master data.
CREATE SQL SECURITY INVOKER VIEW v_application_details AS
SELECT a.id, a.student_id, a.drive_id, a.status, a.applied_at,
       s.enrollment_number, s.full_name, s.branch_id,
       d.title AS drive_title, j.title AS job_title, c.name AS company_name
FROM student_applications AS a
JOIN students AS s ON s.id = a.student_id
JOIN placement_drives AS d ON d.id = a.drive_id
JOIN job_postings AS j ON j.id = d.job_posting_id
JOIN companies AS c ON c.id = j.company_id;

-- Purpose: v_placement_stats_by_branch; demonstrates joins, subqueries or aggregation without duplicated master data.
CREATE SQL SECURITY INVOKER VIEW v_placement_stats_by_branch AS
SELECT b.id AS branch_id, b.code AS branch_code, b.name AS branch_name,
       COUNT(DISTINCT s.id) AS student_count,
       COUNT(DISTINCT CASE WHEN a.status = 'selected' THEN s.id END) AS selected_student_count
FROM branches AS b
LEFT JOIN students AS s ON s.branch_id = b.id
LEFT JOIN student_applications AS a ON a.student_id = s.id
GROUP BY b.id, b.code, b.name;

-- Purpose: preserve immutable application history (BR-12); no status-transition business rules.
CREATE TRIGGER protect_student_applications_delete BEFORE DELETE ON student_applications
FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Application history cannot be deleted';

-- Purpose: preserve immutable application history (BR-12); no status-transition business rules.
CREATE TRIGGER protect_application_status_history_delete BEFORE DELETE ON application_status_history
FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Application history cannot be deleted';
